package dev.danielc.fujiapp;
import android.app.Activity;
import android.os.SystemClock;
import android.widget.*;
/** Passive session information is shown in the currently visible page's window. */
final class CameraDetails {
 static void show(Activity owner,CameraInfo info){if(info==null){Toast.makeText(owner,"相机信息正在准备，请稍候",Toast.LENGTH_SHORT).show();return;}int pad=WorkbenchNav.dp(owner,20);ScrollView scroll=new ScrollView(owner);LinearLayout content=new LinearLayout(owner);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(pad,pad,pad,pad);scroll.addView(content);String[][] rows={{"相机名称",CameraInfo.available(info.name)},{"型号",CameraInfo.available(info.model)},{"厂商",CameraInfo.available(info.manufacturer)},{"设备版本",CameraInfo.available(info.version)},{"序列号",CameraInfo.available(info.serial)},{"连接方式",info.link()},{"连接地址",CameraInfo.available(info.address)},{"照片 / 文件数量",Integer.toString(info.count)},{"本次会话",info.elapsed(SystemClock.elapsedRealtime())}};for(String[] row:rows){TextView label=new TextView(owner);label.setText(row[0]);label.setTextSize(12);label.setTextColor(androidx.core.content.ContextCompat.getColor(owner,R.color.ui_muted));label.setPadding(0,pad/2,0,0);content.addView(label);TextView value=new TextView(owner);value.setText(row[1]);value.setTextSize(16);value.setTextColor(androidx.core.content.ContextCompat.getColor(owner,R.color.ui_text));value.setTextIsSelectable(true);content.addView(value);}TextView note=new TextView(owner);note.setText("信息来自本次相机会话。电量、镜头与存储容量尚未读取；相机没有提供的字段不会使用历史数据补填。");note.setTextSize(12);note.setTextColor(androidx.core.content.ContextCompat.getColor(owner,R.color.ui_muted));note.setPadding(0,pad,0,0);content.addView(note);androidx.appcompat.app.AlertDialog dialog=new androidx.appcompat.app.AlertDialog.Builder(owner).setTitle(info.title()).setView(scroll).setPositiveButton("关闭",null).create();dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().setLayout(-1,(int)(owner.getResources().getDisplayMetrics().heightPixels*0.8));}
}
